# -*- coding: utf-8 -*-
import os

from taf.playwright.sbts.pages.bts_status import BtsStatusPage
from taf.playwright.sbts.pages.login_management import LogoutPage, SbtsLoginPage
from taf.playwright.sbts.pages import v26r3
from taf.playwright.sbts.domains import (
    AlarmsDomain,
    BtsBasicInfoDomain,
    CommissioningDomain,
    ConfigurationDomain,
    DiagnosticDomain,
    PendingDomain,
    PerformanceDomain,
    SoftwareDomain,
)


class Sbts(object):
    """Facade for one Playwright-backed SBTS browser session."""

    def __init__(self, session, screenshot_dir=None):
        self.session = session
        self.page = session.page
        self.screenshot_dir = screenshot_dir
        self._login_page = SbtsLoginPage(self.page)
        self._logout_page = LogoutPage(self.page)
        self._bts_status = BtsStatusPage(self.page)
        self._bts_basic_info = BtsBasicInfoDomain(self._bts_status)
        self._configuration = ConfigurationDomain(self.page)
        self._commissioning = CommissioningDomain(self.page)
        self._diagnostic = DiagnosticDomain(self.page)
        self._software = SoftwareDomain(self.page)
        self._alarms = AlarmsDomain(self.page)
        self._performance = PerformanceDomain(self.page)
        self._security = PendingDomain("security")
        self._options = PendingDomain("options")
        self._browser = PendingDomain("browser")
        self._procedures = PendingDomain("procedures")
        self._rnd_mode = PendingDomain("rnd_mode")
        self._debug = PendingDomain("debug")
        self._user_account_management_for_admin = PendingDomain("user_account_management_for_admin")

    @property
    def login_page(self):
        return self._login_page

    @property
    def logout_page(self):
        return self._logout_page

    @property
    def bts_status(self):
        return self._bts_status

    @property
    def bts_basic_info(self):
        return self._bts_basic_info

    @property
    def configuration(self):
        return self._configuration

    @property
    def commissioning(self):
        return self._commissioning

    @property
    def diagnostic(self):
        return self._diagnostic

    @property
    def software(self):
        return self._software

    @property
    def alarms(self):
        return self._alarms

    @property
    def performance(self):
        return self._performance

    @property
    def security(self):
        return self._security

    @property
    def options(self):
        return self._options

    @property
    def browser(self):
        return self._browser

    @property
    def procedures(self):
        return self._procedures

    @property
    def rnd_mode(self):
        return self._rnd_mode

    @property
    def debug(self):
        return self._debug

    @property
    def user_account_management_for_admin(self):
        return self._user_account_management_for_admin

    def login(self, url, username, password, port=443, ssl=True, timeout=60, readonly=False):
        return self._login_page.login(
            url=url,
            username=username,
            password=password,
            port=port,
            ssl=ssl,
            timeout=timeout,
            readonly=readonly,
        )

    def logout(self, timeout=10):
        self._logout_page.logout(timeout)

    def get_bts_status(self, timeout=5, technology=None):
        return self._bts_status.get_status(timeout=timeout, technology=technology)

    def save_screenshot(self, filename, screenshot_dir=None):
        target_dir = screenshot_dir or self.screenshot_dir
        if not target_dir:
            target_dir = os.getcwd()
        if not os.path.exists(target_dir):
            os.makedirs(target_dir)
        path = os.path.join(target_dir, "{}.png".format(filename))
        self.page.screenshot(path=path, full_page=True)
        return path

    def close(self):
        self.session.close()


class Sbts26R3(Sbts):
    """Default facade for the first Playwright SBTS backend."""

    def __init__(self, session, screenshot_dir=None):
        super(Sbts26R3, self).__init__(session, screenshot_dir)
        self._login_page = v26r3.SbtsLoginPage(self.page)


